-- Correzioni per il DB locale dopo content:catalog (punti 1-3 del reviewer). Idempotente.
begin;

update public.places set description = 'Sperlinga è un piccolo comune della provincia di Enna, poco più di seicento abitanti, tra i Nebrodi e le Madonie. Il castello sorge su uno sperone di arenaria ed è in parte scavato nella roccia, e il borgo conta decine di grotte artificiali. Il paese è citato già in un privilegio del conte Ruggero del 1082, e il castello compare come castrum in un documento del 1239. Durante i Vespri siciliani del 1282 la guarnigione angioina resistette per oltre un anno, e un motto latino sull’arco d’ingresso ricorda l’episodio. La salita avviene per una scalinata ricavata nella pietra.' where slug = 'demo-sperlinga';
update public.activities set description = 'Il castello di Sperlinga sorge su uno sperone di arenaria, nel piccolo comune di Sperlinga, poco più di seicento abitanti tra i Nebrodi e le Madonie. In parte il castello è scavato nella roccia, e il borgo conta decine di grotte artificiali. Il paese è citato già in un privilegio del conte Ruggero del 1082, e il castello compare come castrum in un documento del 1239. Durante i Vespri siciliani del 1282 la guarnigione angioina resistette per oltre un anno, e un motto latino sull’arco d’ingresso ricorda l’episodio. La salita avviene per una scalinata ricavata nella pietra, con un tratto ripido.' where slug = 'demo-sperlinga';
update public.places set description = 'Calascibetta è un borgo medievale sulle alture a ridosso di Enna. A circa tre chilometri dal paese, la necropoli di Realmese scende lungo i pendii del Cozzo San Giuseppe, con un gruppo fitto di tombe a grotticella scavate nella roccia. Le campagne di scavo tra il 1949 e il 1951 hanno portato alla luce 288 tombe. Le fonti datano l’uso del sito tra il IX e il VI secolo a.C., con qualche divergenza, e non hanno ancora individuato l’abitato a cui apparteneva. Nel territorio comunale c’è anche il villaggio bizantino del Canalotto.' where slug = 'demo-calascibetta';
update public.activities set description = 'Calascibetta è un borgo medievale sulle alture a ridosso di Enna. A circa tre chilometri dal paese, la necropoli di Realmese scende lungo i pendii del Cozzo San Giuseppe, con un gruppo fitto di tombe a grotticella scavate nella roccia. Le campagne di scavo tra il 1949 e il 1951 hanno portato alla luce 288 tombe. Le fonti datano l’uso del sito tra il IX e il VI secolo a.C., con qualche divergenza, e non hanno ancora individuato l’abitato a cui apparteneva. Nel territorio comunale c’è anche il villaggio bizantino del Canalotto.' where slug = 'demo-calascibetta';

update public.local_tips set verified_at = current_date - 400 where place_id = (select id from public.places where slug = 'demo-catania') and body = 'Le scarpe comode sono il consiglio più utile: le strade del centro sono pavimentate con pietra lavica, che in caso di umidità diventa scivolosa. In estate porta anche una bottiglia d’acqua, perché il centro è esposto al sole nelle ore centrali.';

commit;
